// Characterization tests: pin CURRENT total/discount behaviour, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 100, D: 100.01, E: 0.1, F: 19.99 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body) => fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('sums unit price * qty across items', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('total is floored to whole euros, not rounded', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 1 }]), 25) // 25.5
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 19) // 19.99
})

test('no discount at exactly 100', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 100)
})

test('10% discount applies strictly above 100', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 90) // 90.009 floored
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  assert.equal(await totalOf([{ sku: 'C', qty: 2 }]), 180)
})

test('discount is flat 10% with no larger tiers for big orders', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 10 }]), 900)
  assert.equal(await totalOf([{ sku: 'C', qty: 100 }]), 9000)
})

test('discount then floor loses up to a euro (e.g. 105.5 -> 94, not 95)', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 1 }, { sku: 'C', qty: 1 }, { sku: 'E', qty: 0 }, { sku: 'A', qty: 0 }]), 100) // 125.5 -> 112.95 -> 112? see below
})

test('order is stored and retrievable with its total', async () => {
  const created = await (await post({ items: [{ sku: 'C', qty: 2 }] })).json()
  const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
  assert.deepEqual(fetched, created)
})

test('validation and unknown routes', async () => {
  assert.equal((await post({ items: [] })).status, 400)
  assert.equal((await post({})).status, 400)
  const missing = await fetch(`${base}/orders/nope`)
  assert.equal(missing.status, 200) // quirk: not-found is a 200
  assert.deepEqual(await missing.json(), { error: 'not found' })
  assert.equal((await fetch(`${base}/nothing`)).status, 404)
})
EOF
